#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# 출시 마법사. 저장소 주인이 자기 Mac에서 처음 출시할 때 손으로 하는 일을 처음부터 끝까지 안내한다.
# 사용법: scripts/release-wizard.sh [--from N | --only N]
# 비밀값(업데이트 서명 개인 키, Flow 키)은 .env에 쓰지 않는다. 개인 키는 pnpm release:keygen이 직접 다룬다.

TOTAL_STAGES=16

# 저장소 루트. 마법사는 어디서 실행해도 루트에서 돈다.
REPO_ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$REPO_ROOT"
# 마법사가 기억하는 공개 값(저장소 주인, 시험 저장소 이름, 스크린숏 경로). .gitignore의 .env*에 걸려 커밋되지 않는다.
ENV_FILE="$REPO_ROOT/.env"
# 사이트를 로컬에서 띄울 때 쓰는 값의 파일(apps/site/.env.example과 같은 키).
SITE_ENV_FILE="$REPO_ROOT/apps/site/.env"
# 점검 결과를 쌓는 파일. 커밋하기 전에 회사 이름·사람 이름·실제 ID가 없는지 본다.
RESULTS_FILE="$REPO_ROOT/docs/checks/macos-release-check.md"
# 앱 저장소 이름. 앱의 업데이트 피드와 빌드 설정(apps/desktop/scripts/build-config.mts)이 이 이름에 묶여 있다.
REPO_NAME="stardraft"
# 사이트 주소.
SITE_URL="https://stardraft.squadify.app"
# 앱 소스의 업데이트 서명 공개 키 목록 파일.
PUBLIC_KEYS_FILE="apps/desktop/src/core/update/update-public-keys.mts"
# 사이트가 실제 스크린숏을 찾는 폴더(apps/site/README.md).
SCREENSHOT_DIR="apps/site/src/assets/screenshots"
# 처음 돌릴 스테이지와 마지막 스테이지.
FROM_STAGE=1
TO_STAGE=$TOTAL_STAGES

# 사용법을 보인다.
usage() {
  cat <<'USAGE'
사용법: scripts/release-wizard.sh [--from N | --only N]
  저장소 주인이 Mac에서 처음 출시할 때 손으로 하는 일을 16개 스테이지로 안내합니다.
  --from N  N번 스테이지부터 이어서 합니다. 중간에 멈췄을 때 씁니다.
  --only N  N번 스테이지 하나만 합니다. 선택 스테이지(13)를 나중에 할 때 씁니다.
  결과는 docs/checks/macos-release-check.md에 쌓입니다.
USAGE
}

# 명령 인수를 읽는다.
parse_args() {
  while (($#)); do
    case "$1" in
      --from) FROM_STAGE="${2:-}"; shift 2 || true ;;
      --only) FROM_STAGE="${2:-}"; TO_STAGE="${2:-}"; shift 2 || true ;;
      -h | --help) usage; exit 0 ;;
      *) usage; exit 1 ;;
    esac
  done
  # 1~16 사이의 숫자인가요?
  if ! [[ "$FROM_STAGE" =~ ^[0-9]+$ && "$TO_STAGE" =~ ^[0-9]+$ ]] || ((FROM_STAGE < 1 || TO_STAGE > TOTAL_STAGES || FROM_STAGE > TO_STAGE)); then
    usage; exit 1
  fi
}

# stop_here "이유"는 지금 스테이지에서 멈추고 이어서 하는 명령을 알려 준다.
stop_here() {
  printf '\n  %s✗ %s%s\n' "$RED" "$1" "$RESET"
  note "고친 뒤 이어서 하기: scripts/release-wizard.sh --from $_STAGE_INDEX"
  exit 1
}

# require "질문"은 y가 아니면 멈춘다.
require() {
  confirm "$1" || stop_here "확인되지 않아 여기서 멈춥니다."
}

# run 명령…은 실행할 명령을 보이고 실행한다.
run() {
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  "$@"
}

# substage "제목"은 한 스테이지 안의 다음 화면으로 넘어간다. 화면을 비우고 스테이지 번호를 다시 보인다.
substage() {
  _clear
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# 결과 파일이 없으면 머리말과 표 머리를 만든다.
_ensure_results() {
  [[ -f "$RESULTS_FILE" ]] && return 0
  mkdir -p "$(dirname "$RESULTS_FILE")"
  {
    printf '# 출시 마법사 점검 결과 (macOS)\n\n'
    printf '%s가 쌓는 기록이다. 회사 이름, 사람 이름, 실제 ID는 적지 않는다.\n\n' "\`scripts/release-wizard.sh\`"
    printf '| 기록 시각 | 스테이지 | 항목 | 결과 | 메모 |\n| :- | :- | :- | :- | :- |\n'
  } >"$RESULTS_FILE"
}

# record_result "항목" "결과" "메모"는 결과 한 줄을 결과 파일에 더한다. 표가 깨지지 않게 |를 /로 바꾼다.
record_result() {
  _ensure_results
  printf '| %s | %s | %s | %s | %s |\n' "$(date '+%Y-%m-%d %H:%M')" "$_STAGE_INDEX" "${1//|//}" "$2" "${3//|//}" >>"$RESULTS_FILE"
  printf '  %s✓ 기록%s %s: %s\n' "$GREEN" "$RESET" "$1" "$2"
}

# record "항목"은 사람이 본 결과(통과·실패·건너뜀)와 메모를 받아 기록한다.
record() {
  local item="$1" reply="" memo="" result
  while :; do
    printf '  %s? %s%s — 결과 [p 통과 / f 실패 / s 건너뜀] ' "$YELLOW" "$item" "$RESET"
    # 입력이 끝났으면(파이프 등) 건너뜀으로 둔다.
    if ! read -r reply; then result="건너뜀"; break; fi
    case "$reply" in
      p | P) result="통과"; break ;;
      f | F) result="실패"; break ;;
      s | S) result="건너뜀"; break ;;
    esac
  done
  printf '  %s메모(본 문구·이유, 회사 이름·사람 이름 없이. 없으면 Enter):%s ' "$DIM" "$RESET"
  read -r memo || true
  record_result "$item" "$result" "$memo"
}

# 저장소 주인 계정. 1단계에서 정한다.
owner() {
  local value
  value=$(_existing GITHUB_OWNER || true)
  [[ -n "$value" ]] || stop_here "저장소 주인을 모릅니다. 1단계부터 다시 하세요: scripts/release-wizard.sh --from 1"
  printf '%s' "$value"
}

# 앱 저장소의 owner/name.
repo() { printf '%s/%s' "$(owner)" "$REPO_NAME"; }

# 데스크톱 앱 패키지의 버전.
app_version() { node -p "require('./apps/desktop/package.json').version"; }

# release_assets VERSION은 그 버전 Release에 있어야 하는 다섯 파일 이름을 정렬해 보인다(apps/desktop/scripts/release-config.mts).
release_assets() {
  printf '%s\n' "Stardraft-$1-arm64.dmg" "Stardraft-$1-arm64-mac.zip" "latest-mac.yml" "Stardraft-Setup-$1.exe" "latest.yml" | LC_ALL=C sort
}

# wait_for_run WORKFLOW BRANCH는 그 브랜치·태그에서 가장 최근 워크플로 실행이 끝날 때까지 지켜본다. 실패하면 거짓.
wait_for_run() {
  local workflow="$1" branch="$2" id="" tries=0
  # 푸시 직후에는 실행이 아직 목록에 없을 수 있다.
  while [[ -z "$id" && $tries -lt 30 ]]; do
    id=$(gh run list --repo "$(repo)" --workflow "$workflow" --branch "$branch" --limit 1 --json databaseId --jq '.[0].databaseId // empty' 2>/dev/null || true)
    [[ -n "$id" ]] || { sleep 4; tries=$((tries + 1)); }
  done
  [[ -n "$id" ]] || { warn "$workflow 실행을 찾지 못했습니다: https://github.com/$(repo)/actions"; return 1; }
  note "https://github.com/$(repo)/actions/runs/$id"
  gh run watch "$id" --repo "$(repo)" --exit-status --interval 10
}

# 로컬 main이 origin/main과 같은지 본다. 태그는 푸시된 커밋에만 단다.
require_synced_main() {
  run git fetch origin main --quiet
  [[ "$(git rev-parse --abbrev-ref HEAD)" == "main" ]] || stop_here "main 브랜치에서 실행하세요(git switch main)."
  [[ -z "$(git status --porcelain)" ]] || stop_here "커밋하지 않은 변경이 있습니다. 정리한 뒤 다시 하세요."
  [[ "$(git rev-parse HEAD)" == "$(git rev-parse origin/main)" ]] || stop_here "로컬 main과 origin/main이 다릅니다. 푸시하거나 당겨서 맞추세요."
}

# commit_and_push "메시지" 파일…은 파일을 커밋하고, 확인을 받아 main에 푸시한 뒤 CI를 지켜본다.
commit_and_push() {
  local message="$1"; shift
  run git add -- "$@"
  if git diff --cached --quiet; then
    note "바뀐 것이 없어 커밋하지 않습니다."
  else
    run git commit -m "$message"
  fi
  if [[ "$(git rev-parse HEAD)" != "$(git rev-parse origin/main 2>/dev/null || true)" ]]; then
    require "main에 푸시할까요? 공개 저장소라 바로 공개됩니다."
    run git push origin main
    wait_for_run ci.yml main || stop_here "CI가 실패했습니다. 고친 뒤 다시 푸시하세요."
  fi
}

# enable_immutable_releases OWNER/NAME은 Release를 공개한 뒤 파일과 태그를 바꿀 수 없게 한다.
# API로 켜 보고, 안 되면 저장소 설정 화면에서 켜게 한다.
enable_immutable_releases() {
  local target="$1" enabled
  gh api -X PUT "repos/$target/immutable-releases" >/dev/null 2>&1 || true
  enabled=$(gh api "repos/$target/immutable-releases" --jq '.enabled' 2>/dev/null || true)
  if [[ "$enabled" == "true" ]]; then
    printf '  %s✓%s %s: immutable releases 켜짐\n' "$GREEN" "$RESET" "$target"
    return 0
  fi
  warn "API로 켜지 못했습니다. 설정 화면에서 켭니다."
  open_url "https://github.com/$target/settings"
  step "General 페이지의 Releases 부분에서 release immutability(변경할 수 없는 Release) 항목을 켜세요."
  note "항목 이름이나 위치가 다르면 GitHub 문서(immutable releases)에서 지금 위치를 확인하세요. 이 마법사는 화면 이름을 확인하지 못했습니다."
  require "$target에서 immutable releases를 켰나요?"
}

# publish_release VERSION은 초안 Release의 노트를 쓰게 하고, 확인을 받아 공개한다.
publish_release() {
  local version="$1"
  # 이어서 하는 경우 이미 공개한 Release는 건너뛴다.
  if [[ "$(gh release view "v$version" --repo "$(repo)" --json isDraft --jq '.isDraft')" != "true" ]]; then
    note "v$version은 이미 공개돼 있습니다."
    return 0
  fi
  open_url "https://github.com/$(repo)/releases/edit/v$version"
  step "릴리스 노트를 씁니다. 사이트의 변경 내역에 그대로 나갑니다. 회사 이름·사람 이름·PR 작성자는 넣지 않습니다."
  step "공개하지 말고 초안으로 저장하세요(Save draft). 공개는 이 마법사가 합니다."
  pause "초안으로 저장했으면 Enter"
  say "저장된 노트:"
  gh release view "v$version" --repo "$(repo)" --json body --jq '.body' | sed 's/^/    /'
  warn "공개하면 immutable releases 때문에 파일과 태그를 다시 바꿀 수 없습니다. 멈추는 방법은 사전 릴리스로 바꾸는 것뿐입니다."
  require "v$version을 공개할까요?"
  run gh release edit "v$version" --repo "$(repo)" --draft=false --latest
}

# push_tag_and_check VERSION은 확인을 받아 태그를 푸시하고, 태그 워크플로가 다섯 파일을 담은 초안 Release를 만들었는지 본다.
push_tag_and_check() {
  local version="$1" actual
  require_synced_main
  [[ "$(app_version)" == "$version" ]] || stop_here "apps/desktop/package.json의 version이 $version이 아닙니다."
  # 공개 키 목록이 비어 있으면 태그 워크플로가 서명을 검증하지 못해 Release를 만들지 않는다.
  grep -qE "^export const UPDATE_PUBLIC_KEYS: readonly string\[\] = \[\];" "$PUBLIC_KEYS_FILE" && stop_here "공개 키 목록이 비어 있습니다. 4단계를 먼저 하세요."
  warn "태그를 푸시하면 태그 워크플로가 빌드하고 서명해 초안 Release를 만듭니다."
  require "main 최신 커밋에 v$version 태그를 달아 푸시할까요?"
  git rev-parse -q --verify "refs/tags/v$version" >/dev/null || run git tag -a "v$version" -m "v$version"
  run git push origin "v$version"
  wait_for_run release.yml "v$version" || stop_here "태그 워크플로가 실패했습니다. 로그의 오류를 고친 뒤, 버전을 올려 새 태그를 달거나 태그를 지우고 다시 다세요."
  actual=$(gh release view "v$version" --repo "$(repo)" --json isDraft,assets --jq 'select(.isDraft) | .assets[].name' | LC_ALL=C sort)
  say "초안 Release v$version의 파일:"
  printf '%s\n' "$actual" | sed 's/^/    /'
  [[ "$actual" == "$(release_assets "$version")" ]] || stop_here "초안 Release의 파일이 다섯 파일(dmg, zip, latest-mac.yml, exe, latest.yml)과 다릅니다."
  printf '  %s✓%s 다섯 파일이 모두 있고 다른 파일은 없습니다.\n' "$GREEN" "$RESET"
}

# 11단계에서 로그아웃하기 전에 남긴, 다시 로그인한 뒤 물을 항목. 있으면 먼저 묻고 지운다.
ask_pending() {
  local pending
  pending=$(_existing RELEASE_WIZARD_PENDING || true)
  [[ -n "$pending" ]] || return 0
  _clear
  printf '\n%s%s▸ 로그아웃 전에 남긴 확인%s\n' "$BOLD" "$BLUE" "$RESET"
  say "다시 로그인했을 때 메뉴 막대에 Stardraft 아이콘이 저절로 나타났나요?"
  _STAGE_INDEX=11
  record "$pending"
  write_env RELEASE_WIZARD_PENDING ""
}

stage_1() {
  stage "GitHub CLI 로그인 확인"
  say "저장소 만들기, 저장소 설정, 비밀값, Release를 모두 gh로 합니다. node와 pnpm도 씁니다."
  # 필요한 명령이 다 있나요?
  local missing=() tool
  for tool in git gh node npm pnpm curl shasum codesign; do
    command -v "$tool" >/dev/null 2>&1 || missing+=("$tool")
  done
  if ((${#missing[@]})); then
    open_url "https://cli.github.com/"
    stop_here "없는 명령: ${missing[*]}. gh는 위 주소의 안내(예: brew install gh), node 24와 pnpm은 저장소의 .node-version과 package.json을 따릅니다."
  fi
  if ! gh auth status --hostname github.com >/dev/null 2>&1; then
    step "브라우저로 gh에 로그인합니다. 화면의 코드를 브라우저에 넣으세요."
    run gh auth login --hostname github.com --git-protocol https --web
  fi
  # 워크플로 파일(.github/workflows)이 든 이력을 푸시하려면 토큰에 workflow 범위가 있어야 한다.
  if ! gh auth status --hostname github.com 2>&1 | grep -q "'workflow'"; then
    step "워크플로 파일을 푸시할 수 있게 workflow 범위를 더합니다."
    run gh auth refresh --hostname github.com --scopes workflow
  fi
  local login
  login=$(gh api user --jq '.login')
  say "로그인한 계정: ${BOLD}$login${RESET}"
  require "이 개인 계정에 공개 저장소 $REPO_NAME을 만들고 출시합니까?"
  write_env GITHUB_OWNER "$login"
  pause "Enter를 누르면 다음 스테이지로"
}

stage_2() {
  stage "이력 검사, 공개 저장소 만들기, CI 확인"
  [[ "$(git rev-parse --abbrev-ref HEAD)" == "main" ]] || stop_here "main 브랜치에서 실행하세요(git switch main)."
  [[ -z "$(git status --porcelain)" ]] || stop_here "커밋하지 않은 변경이 있습니다. 정리한 뒤 다시 하세요."
  say "공개하면 main의 이력 전체가 보입니다. 회사 정보(하위 도메인, 실제 Flow ID)가 남아 있지 않은지 봅니다."

  # Flow 회사 주소(<회사>.flow.team)가 이력 어딘가에 있나요? 공통 API 주소만 허용한다.
  local hosts
  hosts=$(git log main -p --format='%B' | grep -oE '[A-Za-z0-9-]+\.flow\.team' | grep -vx 'api\.flow\.team' | LC_ALL=C sort -u || true)
  if [[ -n "$hosts" ]]; then
    warn "이력에 Flow 회사 주소가 있습니다:"
    printf '%s\n' "$hosts" | sed 's/^/    /'
    stop_here "이력을 고쳐 쓴 뒤(예: git filter-repo) 다시 하세요. 이 마법사는 이력을 고치지 않습니다."
  fi
  printf '  %s✓%s 이력에 api.flow.team 말고 다른 flow.team 주소가 없습니다.\n' "$GREEN" "$RESET"

  say "찾을 값을 하나씩 넣으세요: 회사 하위 도메인, 실제 프로젝트·게시물·사용자 ID, 회사 이름 등."
  note "값은 화면에 보이지 않고 어디에도 저장하지 않습니다. 다 넣었으면 빈 칸으로 Enter."
  local pattern found=0 commits
  while :; do
    pattern=""
    ask_secret pattern "찾을 값:"
    [[ -n "$pattern" ]] || break
    # 그 값을 더하거나 뺀 커밋(-S)과 커밋 메시지에 그 값이 든 커밋을 모두 찾는다.
    commits=$( { git log main --format='%h %ad' --date=short -S "$pattern"; git log main --format='%h %ad' --date=short -F --grep="$pattern"; } | LC_ALL=C sort -u || true)
    if [[ -n "$commits" ]]; then
      found=1
      warn "이 값이 나오는 커밋:"
      printf '%s\n' "$commits" | sed 's/^/    /'
    else
      printf '  %s✓%s 이력에 없습니다.\n' "$GREEN" "$RESET"
    fi
  done
  ((found == 0)) || stop_here "이력에 회사 정보가 남아 있습니다. 가짜 값으로 고쳐 쓴 뒤 다시 하세요."

  say "커밋 작성자 메일 주소도 공개됩니다:"
  git log main --format='%an <%ae>%n%cn <%ce>' | LC_ALL=C sort -u | sed 's/^/    /'
  note "회사 메일이 있으면 공개 전에 바꾸세요(예: git filter-repo의 --mailmap). GitHub의 noreply 주소를 쓸 수 있습니다."
  require "이 이름과 메일 주소가 공개돼도 됩니까?"

  substage "공개 저장소 만들기"
  local origin_url
  origin_url=$(git remote get-url origin 2>/dev/null || true)
  if gh repo view "$(repo)" >/dev/null 2>&1; then
    note "$(repo)가 이미 있습니다. 만들기는 건너뜁니다."
  else
    [[ -z "$origin_url" ]] || stop_here "origin 원격이 이미 있습니다($origin_url). 지우거나 이름을 바꾼 뒤 다시 하세요."
    warn "공개 저장소의 이력은 공개한 뒤 되돌릴 수 없습니다(포크, 캐시, 검색에 남음)."
    require "$(repo)를 공개(MIT) 저장소로 만들고 origin으로 연결할까요?"
    run gh repo create "$(repo)" --public --description "$(node -p "require('./package.json').description")" --source . --remote origin
  fi
  origin_url=$(git remote get-url origin 2>/dev/null || true)
  [[ "$origin_url" =~ github\.com[:/]$(owner)/$REPO_NAME(\.git)?/?$ ]] || stop_here "origin이 $(repo)를 가리키지 않습니다($origin_url). 앱의 업데이트 주소가 origin을 따르므로 맞춰야 합니다."
  if [[ "$(git rev-parse HEAD)" != "$(git rev-parse origin/main 2>/dev/null || true)" ]]; then
    require "main 이력을 푸시할까요?"
    run git push -u origin main
  fi
  note "LICENSE 파일(MIT)이 있어 GitHub가 저장소 첫 화면에 라이선스를 보입니다."
  say "main 푸시의 CI를 지켜봅니다."
  wait_for_run ci.yml main || stop_here "main의 CI가 실패했습니다. 고친 뒤 다시 푸시하세요."

  substage "PR CI 확인"
  say "빈 커밋 하나로 시험 PR을 열어 PR에서도 CI가 도는지 봅니다. 확인한 뒤 PR과 브랜치를 지웁니다."
  if confirm "시험 PR을 열까요?"; then
    # 시험 PR의 브랜치 이름. 겹치지 않게 시각을 붙인다.
    local branch
    branch="ci-check-$(date +%Y%m%d%H%M%S)"
    run git switch -c "$branch"
    run git commit --allow-empty -m "PR CI 확인"
    run git push -u origin "$branch"
    run gh pr create --repo "$(repo)" --base main --head "$branch" --title "PR CI 확인" --body "PR에서 CI가 도는지 확인하고 닫는 PR입니다."
    # 검사가 목록에 오르기까지 잠깐 걸린다.
    sleep 15
    if run gh pr checks "$branch" --repo "$(repo)" --watch --interval 10; then
      record_result "PR CI" "통과" "시험 PR $branch"
    else
      record_result "PR CI" "실패" "시험 PR $branch"
    fi
    run gh pr close "$branch" --repo "$(repo)" --delete-branch
    run git switch main
    # 빈 커밋 하나뿐인 시험 브랜치라 병합 여부와 상관없이 지운다.
    git branch -D "$branch" >/dev/null 2>&1 || true
  else
    record_result "PR CI" "건너뜀" ""
  fi
  pause "Enter를 누르면 다음 스테이지로"
}

stage_3() {
  stage "저장소 설정"
  say "세 가지를 켭니다: immutable releases, 외부 PR 워크플로 승인, release 환경(v* 태그만)."
  enable_immutable_releases "$(repo)"

  # 외부 기여자가 연 PR의 워크플로는 모두 승인한 뒤에만 돈다.
  local policy
  gh api -X PUT "repos/$(repo)/actions/permissions/fork-pr-contributor-approval" -f approval_policy=all_external_contributors >/dev/null 2>&1 || true
  policy=$(gh api "repos/$(repo)/actions/permissions/fork-pr-contributor-approval" --jq '.approval_policy' 2>/dev/null || true)
  if [[ "$policy" == "all_external_contributors" ]]; then
    printf '  %s✓%s 외부 기여자 PR의 워크플로는 승인 뒤에만 돕니다.\n' "$GREEN" "$RESET"
  else
    warn "API로 설정하지 못했습니다. 설정 화면에서 합니다."
    open_url "https://github.com/$(repo)/settings/actions"
    step "Approval for running fork pull request workflows from contributors 부분에서 모든 외부 기여자에게 승인을 요구하는 항목(Require approval for all external contributors)을 고르고 Save."
    note "항목 이름이 다르면 화면에서 가장 엄격한(모든 외부 기여자 승인) 항목을 고르세요."
    require "외부 PR 워크플로 승인을 설정했나요?"
  fi

  # release 환경은 v* 태그에서만 쓸 수 있다. 업데이트 서명 개인 키가 이 환경 비밀값이다.
  local policies
  gh api -X PUT "repos/$(repo)/environments/release" --input - >/dev/null <<'JSON'
{"deployment_branch_policy":{"protected_branches":false,"custom_branch_policies":true}}
JSON
  policies=$(gh api "repos/$(repo)/environments/release/deployment-branch-policies" --jq '.branch_policies[] | "\(.type):\(.name)"')
  if ! grep -qx 'tag:v\*' <<<"$policies"; then
    gh api -X POST "repos/$(repo)/environments/release/deployment-branch-policies" -f name='v*' -f type=tag >/dev/null
    policies=$(gh api "repos/$(repo)/environments/release/deployment-branch-policies" --jq '.branch_policies[] | "\(.type):\(.name)"')
  fi
  say "release 환경의 배포 규칙:"
  printf '%s\n' "$policies" | sed 's/^/    /'
  [[ "$policies" == 'tag:v*' ]] || stop_here "release 환경 규칙이 v* 태그 하나가 아닙니다. 설정 화면에서 다른 규칙을 지우세요: https://github.com/$(repo)/settings/environments"
  open_url "https://github.com/$(repo)/settings/environments"
  step "release 환경을 눌러 Deployment branches and tags에 v* 태그 규칙 하나만 있는지 눈으로 확인하세요."
  require "확인했나요?"
}

stage_4() {
  stage "업데이트 서명 키 만들기"
  say "pnpm release:keygen이 키 쌍을 만들어 개인 키를 release 환경 비밀값과 클립보드에 두고, 공개 키를 앱 소스에 씁니다."
  say "개인 키는 화면에 나오지 않습니다. 클립보드의 값을 비밀번호 관리자에 붙여 넣으라고 할 때 붙여 넣으세요."
  warn "개인 키를 잃으면 업데이트를 서명할 수 없고, 새 키로 바꾸면 그 전 버전의 앱은 업데이트를 받지 못합니다."
  if gh secret list --repo "$(repo)" --env release 2>/dev/null | grep -qE '^UPDATE_SIGNING_KEY[[:space:]]'; then
    note "release 환경에 UPDATE_SIGNING_KEY가 이미 있습니다."
    confirm "키를 이미 만들었으면 키 만들기를 건너뛸까요?" && { commit_and_push "업데이트 서명 공개 키 추가" "$PUBLIC_KEYS_FILE"; return 0; }
  fi
  [[ -d node_modules ]] || run pnpm install --frozen-lockfile
  pause "비밀번호 관리자를 열어 두고 Enter"
  run pnpm release:keygen || stop_here "pnpm release:keygen이 실패했습니다. 위 오류를 보세요."
  gh secret list --repo "$(repo)" --env release | grep -qE '^UPDATE_SIGNING_KEY[[:space:]]' || stop_here "release 환경에 UPDATE_SIGNING_KEY가 없습니다."
  printf '  %s✓%s release 환경 비밀값 UPDATE_SIGNING_KEY가 있습니다.\n' "$GREEN" "$RESET"
  require "비밀번호 관리자에서 저장한 항목을 다시 열어 값이 들어 있는 것을 확인했나요?"
  say "공개 키 목록의 변경:"
  git --no-pager diff --stat -- "$PUBLIC_KEYS_FILE" | sed 's/^/    /'
  commit_and_push "업데이트 서명 공개 키 추가" "$PUBLIC_KEYS_FILE"
}

stage_5() {
  stage "Vercel 프로젝트와 도메인"
  say "먼저 사이트가 GitHub Release를 읽을 때 쓸 공개 읽기 토큰을 만듭니다."
  open_url "https://github.com/settings/personal-access-tokens/new"
  step "Fine-grained token을 만듭니다. 이름은 예: stardraft-site-releases. 만료일을 정하면 만료 전에 다시 만들어 Vercel 값을 바꿉니다."
  step "Repository access는 Public repositories(공개 저장소 읽기만)."
  step "Permissions는 아무것도 더하지 않습니다. Generate token을 누르고 토큰을 복사하세요."
  ask_secret GITHUB_RELEASE_TOKEN "토큰 붙여 넣기:"
  [[ -n "$GITHUB_RELEASE_TOKEN" ]] || stop_here "토큰이 비었습니다."
  # 토큰을 인수로 넘기지 않게 머리글을 표준 입력으로 준다.
  local status
  status=$(printf 'Authorization: Bearer %s\n' "$GITHUB_RELEASE_TOKEN" | curl -sS -o /dev/null -w '%{http_code}' -H @- "https://api.github.com/repos/$(repo)/releases" || true)
  [[ "$status" == "200" ]] || stop_here "토큰으로 Release 목록을 읽지 못했습니다(HTTP $status)."
  printf '  %s✓%s 토큰으로 Release 목록을 읽었습니다.\n' "$GREEN" "$RESET"
  # 사이트를 로컬에서 띄울 때 쓰는 값이다. Vercel에는 아래에서 직접 넣는다.
  local saved_env="$ENV_FILE"
  ENV_FILE="$SITE_ENV_FILE"
  write_env VERCEL_GIT_REPO_OWNER "$(owner)"
  write_env GITHUB_RELEASE_TOKEN "$GITHUB_RELEASE_TOKEN"
  ENV_FILE="$saved_env"

  substage "Vercel 프로젝트 만들기"
  open_url "https://vercel.com/new"
  step "Import Git Repository에서 $(repo)를 고릅니다. 목록에 없으면 Vercel의 GitHub 앱에 이 저장소 접근을 허용하세요."
  step "Root Directory를 Edit로 열어 apps/site를 고릅니다. Framework Preset이 Astro인지 봅니다(apps/site/vercel.json)."
  step "Environment Variables에 GITHUB_RELEASE_TOKEN을 넣습니다. 값은 Enter를 누르면 클립보드에 복사합니다."
  pause "클립보드에 복사하려면 Enter"
  printf '%s' "$GITHUB_RELEASE_TOKEN" | pbcopy
  step "값을 붙여 넣고 Deploy를 누르세요."
  pause "붙여 넣었으면 Enter(클립보드를 비웁니다)"
  printf '' | pbcopy
  step "프로젝트 Settings의 Environment Variables에서 Automatically expose System Environment Variables가 켜져 있는지 봅니다(VERCEL_GIT_REPO_OWNER를 씀)."
  step "프로젝트 Settings의 Git 쪽에서 Ignored Build Step이 비어 있거나 기본값인지 봅니다. 그래야 apps/site/vercel.json의 ignoreCommand가 쓰입니다."
  note "화면 이름이나 위치가 다르면 Vercel 화면에서 같은 설정을 찾아 확인하세요. 이 마법사는 지금 화면을 확인하지 못했습니다."
  require "첫 배포가 Ready가 됐나요?"

  substage "도메인 연결"
  step "프로젝트 Settings의 Domains에서 stardraft.squadify.app을 더합니다."
  step "Vercel이 보여 주는 DNS 레코드(종류, 이름, 값)를 squadify.app의 DNS 관리 화면에 그대로 넣습니다. 값은 Vercel 화면에 나온 것을 씁니다."
  pause "DNS를 넣었으면 Enter(반영까지 몇 분 걸릴 수 있습니다)"
  local page api
  while :; do
    page=$(curl -sS -o /dev/null -w '%{http_code}' "$SITE_URL/" || true)
    api=$(curl -sS -o /dev/null -w '%{http_code}' "$SITE_URL/api/releases" || true)
    say "$SITE_URL/ → HTTP $page, /api/releases → HTTP $api"
    [[ "$page" == "200" && "$api" == "200" ]] && break
    confirm "아직 아닙니다. 다시 확인할까요?" || stop_here "도메인이 아직 연결되지 않았습니다."
  done
  printf '  %s✓%s 사이트가 열립니다. 아직 공개 Release가 없어 다운로드 버튼은 비어 있는 것이 정상입니다.\n' "$GREEN" "$RESET"
  pause "Enter를 누르면 다음 스테이지로"
}

stage_6() {
  stage "시험 저장소에서 사전 릴리스 전환 확인"
  say "잘못 나간 버전은 사전 릴리스로 바꿔 멈춥니다. immutable releases를 켠 저장소에서도 되는지,"
  say "그리고 releases/latest가 이전 버전으로 돌아가는지 시험 저장소에서 먼저 봅니다."
  ask RELEASE_TEST_REPO "시험 저장소 이름(Enter면 stardraft-release-test):"
  [[ -n "$RELEASE_TEST_REPO" ]] || RELEASE_TEST_REPO="stardraft-release-test"
  write_env RELEASE_TEST_REPO "$RELEASE_TEST_REPO"
  # 시험 저장소의 owner/name.
  local test_repo latest
  test_repo="$(owner)/$RELEASE_TEST_REPO"
  if ! gh repo view "$test_repo" >/dev/null 2>&1; then
    require "공개 시험 저장소 $test_repo를 만들까요? 시험이 끝나면 지워도 됩니다."
    run gh repo create "$test_repo" --public --add-readme --description "Release 동작 시험용. 지워도 됩니다."
  fi
  enable_immutable_releases "$test_repo"
  for tag in v0.0.1 v0.0.2; do
    gh release view "$tag" --repo "$test_repo" >/dev/null 2>&1 || run gh release create "$tag" --repo "$test_repo" --target main --title "$tag" --notes "시험"
    # 두 Release의 시각이 겹치지 않게 잠깐 쉰다.
    sleep 3
  done
  latest=$(gh api "repos/$test_repo/releases/latest" --jq '.tag_name')
  say "지금 releases/latest: $latest"
  [[ "$latest" == "v0.0.2" ]] || stop_here "releases/latest가 v0.0.2가 아닙니다. 시험 저장소의 Release 목록을 보세요."

  warn "공개한 v0.0.2를 사전 릴리스로 바꿉니다(시험 저장소)."
  require "바꿀까요?"
  if ! run gh release edit v0.0.2 --repo "$test_repo" --prerelease; then
    record_result "immutable Release의 사전 릴리스 전환" "실패" "gh release edit --prerelease 거부"
    stop_here "immutable Release를 사전 릴리스로 바꾸지 못했습니다. 잘못 나간 버전을 멈추는 방법(스펙 15절)을 다시 정한 뒤 출시하세요."
  fi
  # 바뀐 결과가 API에 보이기까지 잠깐 걸릴 수 있다.
  local tries=0
  while :; do
    latest=$(gh api "repos/$test_repo/releases/latest" --jq '.tag_name')
    [[ "$latest" == "v0.0.1" || $tries -ge 12 ]] && break
    sleep 5; tries=$((tries + 1))
  done
  say "전환 뒤 releases/latest: $latest"
  if [[ "$latest" == "v0.0.1" ]]; then
    record_result "사전 릴리스 전환 뒤 releases/latest" "통과" "v0.0.2 사전 릴리스 → latest v0.0.1"
  else
    record_result "사전 릴리스 전환 뒤 releases/latest" "실패" "전환 뒤 latest $latest"
    stop_here "releases/latest가 이전 버전으로 돌아가지 않았습니다. 스펙 15절의 멈추는 방법을 다시 정한 뒤 출시하세요."
  fi
  note "시험 저장소는 https://github.com/$test_repo/settings 맨 아래에서 지울 수 있습니다."
  pause "Enter를 누르면 다음 스테이지로"
}

stage_7() {
  stage "첫 태그 푸시와 초안 Release 확인"
  local version
  version=$(app_version)
  say "데스크톱 앱 버전: ${BOLD}$version${RESET} (첫 출시는 0.1.0)"
  push_tag_and_check "$version"
  write_env RELEASE_FIRST_VERSION "$version"
  pause "Enter를 누르면 다음 스테이지로"
}

stage_8() {
  stage "초안 Release의 DMG를 브라우저로 받아 설치"
  local version dmg expected actual
  version=$(_existing RELEASE_FIRST_VERSION || app_version)
  say "OS 언어(사이트 스크린숏은 한국어 macOS에서 찍습니다):"
  defaults read -g AppleLanguages 2>/dev/null | tr -d ' \n()"' | sed 's/^/    /'; printf '\n'
  [[ -d /Applications/Stardraft.app ]] && warn "/Applications/Stardraft.app이 이미 있습니다. 처음 설치 경로를 보려면 휴지통으로 옮기고 비운 뒤 진행하세요."
  open_url "https://github.com/$(repo)/releases"
  step "v$version 초안의 Assets에서 Stardraft-$version-arm64.dmg를 눌러 브라우저로 받습니다(터미널로 받으면 실제 경로가 재현되지 않음)."
  ask RELEASE_DMG_PATH "받은 DMG 경로(Enter면 ~/Downloads/Stardraft-$version-arm64.dmg):"
  [[ -n "$RELEASE_DMG_PATH" ]] || RELEASE_DMG_PATH="$HOME/Downloads/Stardraft-$version-arm64.dmg"
  dmg="${RELEASE_DMG_PATH/#\~/$HOME}"
  [[ -f "$dmg" ]] || stop_here "$dmg가 없습니다."
  # 받은 파일이 Release의 파일과 같은가요? GitHub가 파일마다 sha256 digest를 준다.
  expected=$(gh release view "v$version" --repo "$(repo)" --json assets --jq ".assets[] | select(.name == \"Stardraft-$version-arm64.dmg\") | .digest" | sed 's/^sha256://')
  actual=$(shasum -a 256 "$dmg" | cut -d' ' -f1)
  [[ -n "$expected" && "$expected" == "$actual" ]] || stop_here "받은 DMG의 SHA256($actual)이 Release의 값($expected)과 다릅니다."
  printf '  %s✓%s SHA256이 Release와 같습니다.\n' "$GREEN" "$RESET"
  if xattr -p com.apple.quarantine "$dmg" >/dev/null 2>&1; then
    note "격리 속성(com.apple.quarantine)이 있습니다. 실제 설치 경로가 재현됩니다."
  else
    stop_here "받은 DMG에 격리 속성이 없습니다. 브라우저로 다시 받으세요."
  fi

  substage "설치와 첫 실행"
  say "사이트 설치 안내의 macOS 단계를 그대로 따라갑니다. 막히는 두 곳은 그 자리에서 스크린숏을 찍습니다."
  note "스크린숏: Cmd+Shift+4 → Space → 창을 누름. 기본으로 데스크톱에 저장됩니다. 다른 앱 이름이나 계정 이름이 보이지 않게 찍으세요."
  step "DMG를 열고 Stardraft를 Applications 폴더로 끌어 옮긴 뒤, 응용 프로그램 폴더에서 Stardraft를 엽니다."
  step "'Stardraft'을(를) 열지 않음 창이 뜨면 ${BOLD}스크린숏${RESET}을 찍고 ${BOLD}완료${RESET}를 누릅니다(휴지통으로 이동은 누르지 않음)."
  step "시스템 설정 > 개인정보 보호 및 보안의 보안 항목에서 ${BOLD}그래도 열기${RESET}가 보이면 ${BOLD}스크린숏${RESET}을 찍고 누릅니다."
  step "다시 뜨는 창에서 ${BOLD}그래도 열기${RESET}, Mac 로그인 암호, ${BOLD}설정 수정${RESET} 순서로 누릅니다."
  step "메뉴 막대에 Stardraft 아이콘이 보이고 작은 창이 뜨면 끝입니다. Keychain 접근을 묻는 창이 뜨는지도 지켜보세요(11단계에서 묻습니다)."
  note "실제 화면의 문구·버튼 이름이 위와 다르면 메모로 남기세요. 12단계에서 사이트 문구를 맞춥니다."
  record "브라우저로 받은 DMG의 설치 경로(열지 않음 → 그래도 열기)"
  ask MAC_BLOCKED_SHOT "열지 않음 창 스크린숏 경로(없으면 Enter):"
  write_env MAC_BLOCKED_SHOT "$MAC_BLOCKED_SHOT"
  ask MAC_SETTINGS_SHOT "그래도 열기 위치 스크린숏 경로(없으면 Enter):"
  write_env MAC_SETTINGS_SHOT "$MAC_SETTINGS_SHOT"
  pause "Enter를 누르면 다음 스테이지로"
}

