      MAC_BLOCKED_SHOT) dest="$SCREENSHOT_DIR/mac-blocked.png"; ask MAC_BLOCKED_SHOT "열지 않음 창 스크린숏 경로:"; source="$MAC_BLOCKED_SHOT" ;;
